ALTER TABLE "commerce_collection_decisions" ADD CONSTRAINT "commerce_collection_decisions_responsible_carrier_id_commerce_carriers_id_fk" FOREIGN KEY ("responsible_carrier_id") REFERENCES "public"."commerce_carriers"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "commerce_collection_decisions_identity_idx" ON "commerce_collection_decisions" USING btree ("id","order_id","party");--> statement-breakpoint
