ALTER TABLE "commerce_collection_decisions" ADD CONSTRAINT "commerce_collection_decisions_responsibility_check" CHECK ("commerce_collection_decisions"."kind" in ('resolution', 'responsibility_correction') and ("commerce_collection_decisions"."responsible_carrier_id" is null or "commerce_collection_decisions"."party" = 'carrier') and ("commerce_collection_decisions"."supersedes_decision_id" is null or ("commerce_collection_decisions"."supersedes_decision_id" <> "commerce_collection_decisions"."id" and "commerce_collection_decisions"."party" = 'carrier' and "commerce_collection_decisions"."responsible_carrier_id" is not null)) and ("commerce_collection_decisions"."kind" <> 'responsibility_correction' or "commerce_collection_decisions"."supersedes_decision_id" is not null));
